34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.samples.petclinic.util.BusinessDays;
43	import org.springframework.security.access.prepost.PreAuthorize;
44	import org.springframework.web.bind.annotation.CrossOrigin;
45	import org.springframework.web.bind.annotation.RequestMapping;
46	import org.springframework.web.bind.annotation.RestController;
47	import org.springframework.web.util.UriComponentsBuilder;
48	
49	import jakarta.transaction.Transactional;
50	
51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    /** Dedicated audit logger: on a successful create an audit line records the owner id,
61	     * customerCode and registrationDate. */
62	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
63	
64	    /** Maximum number of owners permitted in a single city; the create is rejected at this count. */
65	    private static final int CITY_CAPACITY = 50;
66	
67	    /** Maximum number of owners that may be created on a single day (by registrationDate); the
68	     * create is rejected once this many owners already carry today's registration date. */
69	    private static final int DAILY_REGISTRATION_LIMIT = 100;
70	
71	    /** Once more than this many owners already carry a given day's registration date, a new owner
72	     * created for that day is flagged with {@code bulkSignupWarning} to signal a bulk-signup surge. */
73	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    public OwnerRestControllerV1(ClinicService clinicService,
84	                                 OwnerMapper ownerMapper,
85	                                 PetMapper petMapper,
86	                                 VisitMapper visitMapper) {
87	        this.clinicService = clinicService;
88	        this.ownerMapper = ownerMapper;
89	        this.petMapper = petMapper;
90	        this.visitMapper = visitMapper;
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
96	        Collection<Owner> owners;
97	        if (lastName != null) {
98	            owners = this.clinicService.findOwnerByLastName(lastName);
99	        } else {
100	            owners = this.clinicService.findAllOwners();
101	        }
102	        if (owners.isEmpty()) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
111	        Owner owner = this.clinicService.findOwnerById(ownerId);
112	        if (owner == null) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        HttpHeaders headers = new HttpHeaders();
122	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
123	        // The effective registration date (supplied, or the server date when omitted) must fall on
124	        // a business day: a weekend rolls forward to the next Monday. Everything derived from the
125	        // registration date — the stored value, the per-day limit below and the membership number —
126	        // uses this adjusted date.
127	        LocalDate effectiveDate = BusinessDays.effectiveRegistrationDate(owner.getRegistrationDate());
128	        owner.setRegistrationDate(effectiveDate);
129	        // Per-day capacity: once the day has reached its limit of newly created owners, reject
130	        // further creates for that day with 429 Too Many Requests.
131	        int ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(effectiveDate);
132	        if (ownersRegisteredToday >= DAILY_REGISTRATION_LIMIT) {
133	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
134	        }
135	        // Bulk-signup warning: flag this owner when more than 80 owners have already been created
136	        // for its registration date, signalling a bulk-signup surge.
137	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
138	        // Per-city capacity: a city that already holds the maximum number of owners is full.
139	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
140	            return new ResponseEntity<>(HttpStatus.CONFLICT);
141	        }
142	        // When the owner acknowledges sharing a household with an existing owner (same last name
143	        // and address), assign the shared, stable household identifier (back-filling the existing
144	        // member(s)) before the identity key is computed, so household members carry the same
145	        // householdId component.
146	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
147	        if (sharesHousehold
148	            && this.clinicService.isHouseholdInUse(owner.getLastName(), owner.getAddress())) {
149	            this.clinicService.assignHousehold(owner);
150	        }
151	        // Consolidated duplicate detection: the former separate telephone, email and household
152	        // checks are now expressed through a single derived identityKey. Reject with 409 only when
153	        // the new owner's WHOLE identityKey (normalized telephone | email-or-empty | householdId)
154	        // equals an existing owner's; an exact full-key match is the only duplicate.
155	        if (this.clinicService.isIdentityKeyInUse(owner)) {
156	            return new ResponseEntity<>(HttpStatus.CONFLICT);
157	        }
158	        owner.setNamesakeCount(
159	            this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
160	        this.clinicService.saveOwner(owner);
161	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
162	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
163	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
164	        headers.setLocation(UriComponentsBuilder.newInstance()
165	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
166	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
167	    }
168	
169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Override
171	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
172	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
173	        if (currentOwner == null) {
174	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
175	        }
176	        currentOwner.setAddress(ownerFieldsDto.getAddress());
177	        currentOwner.setCity(ownerFieldsDto.getCity());
178	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
179	        currentOwner.setLastName(ownerFieldsDto.getLastName());
180	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
181	        currentOwner.setEmail(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
182	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
183	        this.clinicService.saveOwner(currentOwner);
184	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Transactional
189	    @Override
190	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
191	        Owner owner = this.clinicService.findOwnerById(ownerId);
192	        if (owner == null) {
193	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	        }
195	        this.clinicService.deleteOwner(owner);
196	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
197	    }
198	
199	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
200	    @Override
201	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
202	        Owner owner = this.clinicService.findOwnerById(ownerId);
203	        if (owner == null) {
204	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
205	        }
206	        HttpHeaders headers = new HttpHeaders();
207	        Pet pet = petMapper.toPet(petFieldsDto);
208	        owner.setId(ownerId);
209	        pet.setOwner(owner);
210	        pet.getType().setName(null);
211	        this.clinicService.savePet(pet);
212	        PetDto petDto = petMapper.toPetDto(pet);
213	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
214	            .buildAndExpand(pet.getId()).toUri());
215	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
216	    }
217	
218	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
219	    @Override
220	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
221	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
222	        if (currentOwner != null) {
223	            Pet currentPet = this.clinicService.findPetById(petId);
224	            if (currentPet != null) {
225	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
226	                currentPet.setName(petFieldsDto.getName());
227	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
228	                this.clinicService.savePet(currentPet);
229	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
230	            }
231	        }
232	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
233	    }
234	
235	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
236	    @Override
237	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
238	        HttpHeaders headers = new HttpHeaders();
239	        Visit visit = visitMapper.toVisit(visitFieldsDto);
240	        Pet pet = new Pet();
241	        pet.setId(petId);
242	        visit.setPet(pet);
243	        this.clinicService.saveVisit(visit);
244	        VisitDto visitDto = visitMapper.toVisitDto(visit);
245	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
246	            .buildAndExpand(visit.getId()).toUri());
247	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
248	    }
249	
250	
251	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
252	    @Override
253	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
254	        Owner owner = this.clinicService.findOwnerById(ownerId);
255	        if (owner != null) {
256	            Pet pet = owner.getPet(petId);
257	            if (pet != null) {
258	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
259	            }
260	        }
261	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
262	    }
263	}
